:root {
  --bg: #0c0f13;
  --text: #edf2f7;
  --muted: #7d8895;
  --accent: #f6ad55;
  --danger: #fc8181;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, sans-serif;
  text-align: center;
}
h1 { margin: 0; }
.tagline { color: var(--muted); }
.controls { display: flex; gap: 20px; justify-content: center; margin: 24px 0; }
.controls label { display: grid; gap: 6px; color: var(--muted); font-size: 0.9rem; }
input {
  font: inherit;
  width: 110px;
  padding: 8px 10px;
  background: #151a21;
  color: var(--text);
  border: 1px solid #2a3340;
  border-radius: 8px;
  text-align: center;
}
#cost {
  display: block;
  font-size: clamp(3rem, 12vw, 6rem);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--accent);
}
#cost.hot { color: var(--danger); }
#elapsed { color: var(--muted); font-variant-numeric: tabular-nums; }
.buttons { display: flex; gap: 12px; justify-content: center; }
button {
  font: inherit;
  padding: 12px 28px;
  border-radius: 10px;
  border: none;
  background: var(--accent);
  color: #1a1005;
  cursor: pointer;
}
button.ghost { background: transparent; color: var(--muted); border: 1px solid #2a3340; }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }

// meeting-meter — drift-free live cost counter.
// We never "count up"; we always derive cost from (now - startedAt),
// so background-tab throttling can't make the number lie.

const peopleEl = document.getElementById("people");
const rateEl = document.getElementById("rate");
const costEl = document.getElementById("cost");
const elapsedEl = document.getElementById("elapsed");
const toggleBtn = document.getElementById("toggle");
const resetBtn = document.getElementById("reset");

let startedAt = null;   // timestamp of current run
let banked = 0;         // ms accumulated across previous runs (pause support)
let rafId = null;

function elapsedMs() {
  return banked + (startedAt ? Date.now() - startedAt : 0);
}

function currentCost() {
  const people = Math.max(1, Number(peopleEl.value) || 1);
  const rate = Math.max(0, Number(rateEl.value) || 0);
  const hours = elapsedMs() / 3_600_000;
  return people * rate * hours;
}

function fmtClock(ms) {
  const s = Math.floor(ms / 1000);
  const pad = (n) => String(n).padStart(2, "0");
  return `${pad(Math.floor(s / 3600))}:${pad(Math.floor((s % 3600) / 60))}:${pad(s % 60)}`;
}

function tick() {
  const cost = currentCost();
  costEl.textContent = cost.toFixed(2);
  costEl.classList.toggle("hot", cost >= 100); // psychology: it turns red
  elapsedEl.textContent = fmtClock(elapsedMs());
  rafId = requestAnimationFrame(tick);
}

toggleBtn.addEventListener("click", () => {
  if (startedAt) {
    banked += Date.now() - startedAt;   // pause
    startedAt = null;
    cancelAnimationFrame(rafId);
    toggleBtn.textContent = "Resume";
  } else {
    startedAt = Date.now();             // start / resume
    toggleBtn.textContent = "Pause";
    tick();
  }
});

resetBtn.addEventListener("click", () => {
  startedAt = null;
  banked = 0;
  cancelAnimationFrame(rafId);
  toggleBtn.textContent = "Start";
  costEl.textContent = "0.00";
  costEl.classList.remove("hot");
  elapsedEl.textContent = "00:00:00";
});
